package com.projetok.studio;
import javax.swing.*;
import java.awt.*;
import java.util.*;

/** Edicao de portais e visualizacao de ligacoes entre mapas conhecidos. */
final class PortalTools {
    final WorldStudio ui;
    PortalTools(WorldStudio ui){this.ui=ui;ui.action("Mapa","Novo portal",()->edit(null));ui.action("Mapa","Editar portal",()->{String id=(String)JOptionPane.showInputDialog(ui,"Portal","Editar",JOptionPane.PLAIN_MESSAGE,null,ui.document.portals().stream().map(WorldDocument.Portal::id).toArray(String[]::new),null);if(id!=null)edit(ui.document.portals().stream().filter(p->p.id().equals(id)).findFirst().orElseThrow());});ui.action("Mapa","Conexoes entre mapas",this::graph);}
    void edit(WorldDocument.Portal old){JPanel form=new JPanel(new GridLayout(0,2));String[] labels={"ID","Origem X","Origem Y","Mapa destino (ID)","Chegada X","Chegada Y","Missao aceita (opcional)","Orientacao"};String[] defaults=old==null?new String[]{EditorOperations.id(),""+Math.max(18,ui.lastCursor.x),""+Math.max(18,ui.lastCursor.y),ui.document.id(),"140","320","","FRONT"}:new String[]{old.id(),""+old.x(),""+old.y(),old.destination(),""+old.arrivalX(),""+old.arrivalY(),old.quest(),old.direction()};JTextField[] f=new JTextField[8];for(int i=0;i<8;i++){form.add(new JLabel(labels[i]));f[i]=new JTextField(defaults[i]);form.add(f[i]);}if(JOptionPane.showConfirmDialog(ui,form,"Portal",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;
        var portal=new WorldDocument.Portal(f[0].getText(),Integer.parseInt(f[1].getText()),Integer.parseInt(f[2].getText()),f[3].getText(),Integer.parseInt(f[4].getText()),Integer.parseInt(f[5].getText()),f[6].getText(),f[7].getText());var next=new ArrayList<>(ui.document.portals());if(old!=null)next.remove(old);next.add(portal);ui.change(ui.document.withPortals(next));ui.details.setText(PortalGraph.validate(ui.maps()).toString());}
    void graph(){var maps=ui.maps();var ids=new ArrayList<>(maps.keySet());Collections.sort(ids);JPanel panel=new JPanel(){protected void paintComponent(Graphics original){super.paintComponent(original);Graphics2D g=(Graphics2D)original.create();try{Map<String,Point> points=new HashMap<>();for(int i=0;i<ids.size();i++)points.put(ids.get(i),new Point(30+i%3*190,40+i/3*90));g.setColor(Color.GRAY);for(var d:maps.values())for(var p:d.portals())if(points.containsKey(p.destination())){Point a=points.get(d.id()),b=points.get(p.destination());g.drawLine(a.x+70,a.y+20,b.x+70,b.y+20);}for(String id:ids){Point p=points.get(id);g.setColor(new Color(55,100,95));g.fillRoundRect(p.x,p.y,150,40,10,10);g.setColor(Color.WHITE);g.drawString(id,p.x+8,p.y+24);}}finally{g.dispose();}}};panel.setPreferredSize(new Dimension(620,Math.max(220,((ids.size()+2)/3)*90+60)));JPanel all=new JPanel(new BorderLayout());all.add(new JScrollPane(panel));JTextArea errors=new JTextArea(String.join("\n",PortalGraph.validate(maps).stream().map(Object::toString).toList()),5,60);errors.setEditable(false);all.add(new JScrollPane(errors),BorderLayout.SOUTH);JOptionPane.showMessageDialog(ui,all,"Conexoes: linhas nao substituem validacao",JOptionPane.PLAIN_MESSAGE);}
}
